CREATE TABLE IF NOT EXISTS org_departments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, description text, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS org_positions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, department_id uuid REFERENCES org_departments(id), reports_to_position_id uuid REFERENCES org_positions(id), employment_type text NOT NULL DEFAULT 'full_time', level text, status text NOT NULL DEFAULT 'planned', description text, responsibilities text, required_qualifications text, required_skills text, location_type text DEFAULT 'hybrid', salary_band text, statutory_role boolean NOT NULL DEFAULT false, target_start_date date, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(title, department_id));
CREATE TABLE IF NOT EXISTS people_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), full_name text NOT NULL, email text, phone text, position_id uuid REFERENCES org_positions(id), person_type text NOT NULL DEFAULT 'employee', lifecycle_status text NOT NULL DEFAULT 'talent_pool', nationality text, residential_address text, cv_document text, identity_document text, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS recruitment_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), person_id uuid REFERENCES people_records(id) ON DELETE CASCADE, event_type text NOT NULL, status text, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS employee_onboarding (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), person_id uuid UNIQUE REFERENCES people_records(id) ON DELETE CASCADE, start_date date, manager_position_id uuid REFERENCES org_positions(id), onboarding_status text NOT NULL DEFAULT 'not_started', documents_complete boolean NOT NULL DEFAULT false, access_complete boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_people_position ON people_records(position_id);
CREATE INDEX IF NOT EXISTS idx_people_status ON people_records(lifecycle_status);